scwin.fireOver = function(node) {
    if (document.createEventObject) {
        node.fireEvent("onmouseover");
    } else if (document.createEvent) {
        var evt = document.createEvent("MouseEvents");
        evt.initEvent("mouseover", true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.onmouseover == "function") {
        node.onmouseover();
    }
}
scwin.mouseOverBehaviour = function(id){
	var el = WebSquare.wUnit.getDomById(id);
	scwin.fireOver(el);
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.mouseOverBehaviour('gridView1_column1')");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('wq_uuid_2_balloonTip').style.display", "block");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_2_balloonTip').css('opacity')", "1");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
